command:
if (!game.user.isGM) {
  ui.notifications.warn("GM only.");
  return;
}
const scene = canvas.scene;
if (!scene) {
  ui.notifications.warn("No active scene.");
  return;
}
const updates = [];
let skipped = 0;
for (const note of scene.notes) {
  if (note.text) continue;
  const label = note.page?.name ?? note.entry?.name;
  if (!label) { skipped++; continue; }
  updates.push({ _id: note.id, text: label });
}
if (updates.length) await scene.updateEmbeddedDocuments("Note", updates);
ui.notifications.info(`Labeled ${updates.length} pin(s)${skipped ? `, skipped ${skipped} with no linked journal` : ""}.`);
